import { readdir, stat, mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';

const dir = path.resolve(process.argv[2] ?? path.join(os.homedir(), 'lab', 'data'));
const entries = await readdir(dir, { withFileTypes: true });

const rows = [];
for (const entry of entries) {
  if (!entry.isFile()) continue; // skips archive/ and other folders
  const full = path.join(dir, entry.name);
  const info = await stat(full);
  rows.push({ name: entry.name, ext: path.extname(entry.name), bytes: info.size });
}
rows.sort((a, b) => b.bytes - a.bytes);
console.table(rows);

await mkdir('out', { recursive: true }); // no error if it already exists
const target = path.join('out', 'inventory.json');
await writeFile(target, JSON.stringify(rows, null, 2) + '\n');
console.log(`wrote ${rows.length} rows to ${target}`);

