#!/usr/bin/env node
// codes.js: count HTTP status codes in a combined-format log read from stdin
//   node codes.js < ~/lab/access.log      or      cat ~/lab/access.log | node codes.js
import readline from 'node:readline';

// the reader of our stdout (head, less) may exit early: stop quietly instead of crashing
process.stdout.on('error', (err) => {
  if (err.code === 'EPIPE') process.exit(0);
  throw err;
});

const counts = new Map();
const rl = readline.createInterface({ input: process.stdin, crlfDelay: Infinity });

for await (const line of rl) { // one complete line per iteration, however the bytes arrived
  const status = line.split('"')[2]?.trim().split(' ')[0]; // text after the request: ' 404 782 '
  if (!/^\d{3}$/.test(status ?? '')) {
    console.error(`skipping: ${line.slice(0, 40)}`);
    continue;
  }
  counts.set(status, (counts.get(status) ?? 0) + 1);
}

for (const [status, n] of [...counts].sort((a, b) => b[1] - a[1])) {
  process.stdout.write(`${status}\t${n}\n`);
}

// gzip.js: compress a file through a stream pipeline (constant memory, any file size)
import { createReadStream, createWriteStream } from 'node:fs';
import { stat } from 'node:fs/promises';
import { pipeline } from 'node:stream/promises';
import { createGzip } from 'node:zlib';

const src = process.argv[2];
if (!src) {
  console.error('usage: node gzip.js FILE');
  process.exit(2);
}
const dest = `${src}.gz`;

await pipeline(createReadStream(src), createGzip(), createWriteStream(dest));

const [before, after] = await Promise.all([stat(src), stat(dest)]);
console.log(`${src}: ${before.size} -> ${after.size} bytes (${((after.size / before.size) * 100).toFixed(1)}%)`);

