// How a node:http handler sees a request: req.method and req.url (path + query, as sent)
const routes = [
  ['GET', /^\/api\/devices$/, () => 'list devices'],
  ['POST', /^\/api\/devices$/, () => 'create a device'],
  ['GET', /^\/api\/devices\/(\d+)$/, (id) => `device ${id}`],
];

function route(method, rawUrl) {
  const url = new URL(rawUrl, 'http://localhost'); // a base is required: req.url has no host
  const hits = routes.filter(([, re]) => re.test(url.pathname));
  if (hits.length === 0) return `404 no route for ${url.pathname}`;
  const hit = hits.find(([m]) => m === method);
  if (!hit) return `405 allowed: ${hits.map(([m]) => m).join(', ')}`;
  const params = url.pathname.match(hit[1]).slice(1);
  return `200 ${hit[2](...params)} ${JSON.stringify(Object.fromEntries(url.searchParams))}`;
}

