// app.js: a small web server on node:http, no dependencies
import http from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';

const PUBLIC = path.join(import.meta.dirname, 'public');
const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
};
const MAX_BODY = 1_000_000; // bytes; refuse anything bigger

function sendJson(res, status, data, headers = {}) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body), // bytes, not characters
    ...headers,
  });
  res.end(body);
}

async function readBody(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) { // req is a readable stream of Buffers
    size += chunk.length;
    if (size > MAX_BODY) throw Object.assign(new Error('body too large'), { status: 413 });
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf8');
}

async function serveStatic(res, pathname) {
  const file = path.join(PUBLIC, pathname === '/' ? 'index.html' : pathname);
  if (!file.startsWith(PUBLIC + path.sep)) return sendJson(res, 403, { error: 'forbidden' });
  try {
    const data = await readFile(file);
    res.writeHead(200, {
      'Content-Type': TYPES[path.extname(file)] ?? 'application/octet-stream',
      'Content-Length': data.length,
    });
    res.end(data);
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'EISDIR') return sendJson(res, 404, { error: `not found: ${pathname}` });
    throw err;
  }
}

async function handle(req, res) {
  const url = new URL(req.url, 'http://localhost'); // req.url is only the path and query

  if (url.pathname === '/api/status') {
    if (req.method !== 'GET') return sendJson(res, 405, { error: 'use GET' }, { Allow: 'GET' });
    return sendJson(res, 200, { host: os.hostname(), uptime: Math.round(process.uptime()), node: process.version });
  }

  if (url.pathname === '/api/echo') {
    if (req.method !== 'POST') return sendJson(res, 405, { error: 'use POST' }, { Allow: 'POST' });
    if (!req.headers['content-type']?.startsWith('application/json')) {
      return sendJson(res, 415, { error: 'send Content-Type: application/json' });
    }
    let body;
    try {
      body = JSON.parse(await readBody(req));
    } catch (err) {
      if (err.status) throw err; // 413 from readBody
      return sendJson(res, 400, { error: 'body must be JSON' });
    }
    return sendJson(res, 200, { query: Object.fromEntries(url.searchParams), body });
  }

  if (req.method === 'GET' || req.method === 'HEAD') return serveStatic(res, decodeURIComponent(url.pathname));
  return sendJson(res, 404, { error: `no route for ${req.method} ${url.pathname}` });
}

export function createServer({ log = console.log } = {}) {
  return http.createServer((req, res) => {
    res.on('finish', () => log(`${req.method} ${req.url} -> ${res.statusCode}`));
    handle(req, res).catch((err) => {
      if (!err.status) console.error(err); // a bug: show the stack in the server's terminal
      if (res.headersSent) return res.destroy();
      sendJson(res, err.status ?? 500, { error: err.status ? err.message : 'internal server error' });
    });
  });
}

