const parse = (v) => v.split('.').map(Number);

function satisfies(version, range) {
  const [, op, base] = range.match(/^([\^~]?)(.+)$/);
  const [M, m, p] = parse(base);
  const [vM, vm, vp] = parse(version);
  const atLeast = vM > M || (vM === M && (vm > m || (vm === m && vp >= p)));
  if (op === '') return vM === M && vm === m && vp === p;
  if (op === '~') return atLeast && vM === M && vm === m;
  if (M > 0) return atLeast && vM === M;            // ^1.4.2 means >=1.4.2 <2.0.0
  if (m > 0) return atLeast && vM === 0 && vm === m; // ^0.4.2 means >=0.4.2 <0.5.0
  return vM === 0 && vm === 0 && vp === p;          // ^0.0.3 means exactly 0.0.3
}

for (const v of ['1.4.1', '1.4.2', '1.4.9', '1.9.0', '2.0.0']) {
  console.log(v.padEnd(6), '^1.4.2', satisfies(v, '^1.4.2'), ' ~1.4.2', satisfies(v, '~1.4.2'));
}

// A model of Express's middleware loop: the order is the program
function createApp() {
  const stack = [];
  return {
    use(fn) { stack.push(fn); },
    handle(req, res) {
      let i = 0;
      const next = (err) => {
        const fn = stack[i++];
        if (!fn) return console.log('end of stack:', err ? `unhandled ${err.message}` : '404');
        const isErrorHandler = fn.length === 4; // Express really counts the parameters
        if (err && isErrorHandler) return fn(err, req, res, next);
        if (!err && !isErrorHandler) {
          try { return fn(req, res, next); } catch (e) { return next(e); }
        }
        next(err); // wrong kind of middleware for the current state: skip it
      };
      next();
    },
  };
}

const app = createApp();
app.use((req, res, next) => { console.log('1 logger', req.method, req.url); next(); });
app.use((req, res, next) => { if (req.url === '/boom') throw new Error('kaboom'); next(); });
app.use((req, res, next) => { if (req.url === '/api/status') return console.log('2 route: send JSON'); next(); });
app.use((err, req, res, next) => console.log('3 error handler:', err.message));

app.handle({ method: 'GET', url: '/api/status' }, {});
app.handle({ method: 'GET', url: '/boom' }, {});
app.handle({ method: 'GET', url: '/nope' }, {});

// express-server.js: the node:http server from app.js, rebuilt with Express 5
import express from 'express';
import { readFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { serviceName } from './lib/netutil.js';

const app = express();
const ALLOWED_ORIGINS = new Set(['http://localhost:8000']); // pages allowed to call /api from a browser

// 1. logger: every request passes through here first
app.use((req, res, next) => {
  res.on('finish', () => console.log(`${req.method} ${req.originalUrl} -> ${res.statusCode}`));
  next(); // hand over to the next middleware; forget this and the request hangs
});

// 2. CORS for the API: tell browsers which other origins may read our responses
app.use('/api', (req, res, next) => {
  const origin = req.get('Origin');
  if (origin && ALLOWED_ORIGINS.has(origin)) {
    res.set('Access-Control-Allow-Origin', origin);
    res.set('Vary', 'Origin');
  }
  if (req.method === 'OPTIONS') { // preflight: answer it here, never reach the routes
    res.set('Access-Control-Allow-Methods', 'GET, POST');
    res.set('Access-Control-Allow-Headers', 'Content-Type');
    res.set('Access-Control-Max-Age', '600');
    return res.sendStatus(204);
  }
  next();
});

// 3. static files from public/ (index.html for /), 4. JSON body parser
app.use(express.static(path.join(import.meta.dirname, 'public')));
app.use(express.json({ limit: '1mb' }));

// 5. routes
app.get('/api/status', (req, res) => {
  res.json({ host: os.hostname(), uptime: Math.round(process.uptime()), node: process.version });
});

app.post('/api/echo', (req, res) => {
  if (!req.is('application/json')) return res.status(415).json({ error: 'send Content-Type: application/json' });
  res.json({ query: req.query, body: req.body });
});

app.get('/api/ports/:port', (req, res) => { // :port is a route parameter
  const port = Number(req.params.port);
  if (!Number.isInteger(port) || port < 1 || port > 65535) return res.status(400).json({ error: 'port must be 1-65535' });
  res.json({ port, service: serviceName(port) });
});

app.get('/api/log', async (req, res) => { // async handler: a rejection goes to the error handler
  const lines = Number(req.query.lines ?? 3);
  const text = await readFile(path.join(os.homedir(), 'lab', 'access.log'), 'utf8');
  res.type('text/plain').send(text.trimEnd().split('\n').slice(-lines).join('\n') + '\n');
});

// 6. nothing matched under /api: JSON 404 instead of Express's HTML page
app.use('/api', (req, res) => res.status(404).json({ error: `no route for ${req.method} ${req.originalUrl}` }));

// 7. error handler: exactly four parameters
app.use((err, req, res, next) => {
  if (err.type === 'entity.parse.failed') return res.status(400).json({ error: 'body must be JSON' });
  console.error(err);
  res.status(err.status ?? 500).json({ error: err.expose ? err.message : 'internal server error' });
});

