#!/usr/bin/env node
// top.js: print the N busiest client IPs of a web log read on stdin
import readline from 'node:readline';

process.stdout.on('error', (err) => {
  if (err.code === 'EPIPE') process.exit(0);
  throw err;
});

const n = Number(process.argv[2] ?? 10);
if (!Number.isInteger(n) || n < 1) {
  console.error('usage: node top.js [N] < access.log');
  process.exit(2);
}

const counts = new Map();
for await (const line of readline.createInterface({ input: process.stdin, crlfDelay: Infinity })) {
  const ip = line.split(' ', 1)[0];
  if (ip) counts.set(ip, (counts.get(ip) ?? 0) + 1);
}

const ranked = [...counts].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
for (const [ip, count] of ranked.slice(0, n)) {
  process.stdout.write(`${String(count).padStart(7)} ${ip}\n`);
}

// devices-http.js: a JSON API for lab devices on node:http (data lives in memory)
import http from 'node:http';

const devices = [
  { id: 1, name: 'router', ip: '192.168.1.1', type: 'router' },
  { id: 2, name: 'pi', ip: '192.168.1.50', type: 'server' },
  { id: 3, name: 'nas', ip: '192.168.1.60', type: 'storage' },
];
let nextId = 4;
const IPV4 = /^((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;

function send(res, status, data, headers = {}) {
  const body = JSON.stringify(data);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body), ...headers });
  res.end(body);
}

async function readJson(req) {
  let text = '';
  for await (const chunk of req) {
    text += chunk;
    if (text.length > 100_000) throw new Error('too large');
  }
  return JSON.parse(text); // throws SyntaxError on bad JSON
}

function problem(body) {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) return 'body must be a JSON object';
  if (typeof body.name !== 'string' || body.name.trim() === '') return 'name is required';
  if (typeof body.ip !== 'string' || !IPV4.test(body.ip)) return 'ip must be an IPv4 address';
  return null;
}

const server = http.createServer(async (req, res) => {
  const { pathname, searchParams } = new URL(req.url, 'http://localhost');
  const byId = pathname.match(/^\/api\/devices\/(\d+)$/);
  try {
    if (pathname === '/api/devices' && req.method === 'GET') {
      const type = searchParams.get('type');
      return send(res, 200, type ? devices.filter((d) => d.type === type) : devices);
    }
    if (pathname === '/api/devices' && req.method === 'POST') {
      let body;
      try {
        body = await readJson(req);
      } catch {
        return send(res, 400, { error: 'body must be JSON' });
      }
      const why = problem(body);
      if (why) return send(res, 422, { error: why });
      const device = { id: nextId++, name: body.name.trim(), ip: body.ip, type: body.type ?? 'unknown' };
      devices.push(device);
      return send(res, 201, device, { Location: `/api/devices/${device.id}` });
    }
    if (byId && req.method === 'GET') {
      const device = devices.find((d) => d.id === Number(byId[1]));
      return device ? send(res, 200, device) : send(res, 404, { error: `device ${byId[1]} not found` });
    }
    send(res, 404, { error: `no route for ${req.method} ${pathname}` });
  } catch (err) {
    console.error(err);
    send(res, 500, { error: 'internal server error' });
  }
});

server.listen(3000, '127.0.0.1', () => console.log('devices API on http://127.0.0.1:3000'));

// devices-express.js: the same devices API with Express 5
import express from 'express';

const devices = [
  { id: 1, name: 'router', ip: '192.168.1.1', type: 'router' },
  { id: 2, name: 'pi', ip: '192.168.1.50', type: 'server' },
  { id: 3, name: 'nas', ip: '192.168.1.60', type: 'storage' },
];
let nextId = 4;
const IPV4 = /^((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;

const app = express();
app.use(express.json());

app.get('/api/devices', (req, res) => {
  const { type } = req.query;
  res.json(type ? devices.filter((d) => d.type === type) : devices);
});

app.get('/api/devices/:id', (req, res) => {
  const device = devices.find((d) => d.id === Number(req.params.id));
  if (!device) return res.status(404).json({ error: `device ${req.params.id} not found` });
  res.json(device);
});

app.post('/api/devices', (req, res) => {
  if (!req.is('application/json')) return res.status(415).json({ error: 'send Content-Type: application/json' });
  const { name, ip, type = 'unknown' } = req.body;
  if (typeof name !== 'string' || name.trim() === '') return res.status(422).json({ error: 'name is required' });
  if (typeof ip !== 'string' || !IPV4.test(ip)) return res.status(422).json({ error: 'ip must be an IPv4 address' });
  const device = { id: nextId++, name: name.trim(), ip, type };
  devices.push(device);
  res.status(201).location(`/api/devices/${device.id}`).json(device);
});

app.use((req, res) => res.status(404).json({ error: `no route for ${req.method} ${req.path}` }));

app.use((err, req, res, next) => {
  if (err.type === 'entity.parse.failed') return res.status(400).json({ error: 'body must be JSON' });
  console.error(err);
  res.status(500).json({ error: 'internal server error' });
});

app.listen(3000, '127.0.0.1', (err) => {
  if (err) {
    console.error(`cannot listen: ${err.message}`);
    process.exit(1);
  }
  console.log('devices API on http://127.0.0.1:3000');
});

// test/devices.test.js: API tests for devices-app.js
import { describe, it, before, after } from 'node:test';
import { once } from 'node:events';
import assert from 'node:assert/strict';
import app from '../devices-app.js';

let server;
let base;
before(async () => {
  server = app.listen(0, '127.0.0.1');
  await once(server, 'listening');
  base = `http://127.0.0.1:${server.address().port}/api/devices`;
});
after(() => server.close());

const post = (body, type = 'application/json') =>
  fetch(base, { method: 'POST', headers: { 'Content-Type': type }, body: typeof body === 'string' ? body : JSON.stringify(body) });

describe('GET', () => {
  it('lists the seed devices', async () => {
    const res = await fetch(base);
    assert.equal(res.status, 200);
    assert.deepEqual((await res.json()).map((d) => d.name), ['router', 'pi', 'nas']);
  });
  it('filters by type', async () => {
    const list = await (await fetch(`${base}?type=server`)).json();
    assert.deepEqual(list.map((d) => d.id), [2]);
  });
  it('answers 404 with a JSON error for an unknown id', async () => {
    const res = await fetch(`${base}/99`);
    assert.equal(res.status, 404);
    assert.deepEqual(await res.json(), { error: 'device 99 not found' });
  });
});

describe('POST', () => {
  it('creates a device: 201, Location, then readable by id', async () => {
    const res = await post({ name: 'printer', ip: '192.168.1.70', type: 'printer' });
    assert.equal(res.status, 201);
    const created = await res.json();
    assert.equal(res.headers.get('location'), `/api/devices/${created.id}`);
    assert.deepEqual(await (await fetch(`${base}/${created.id}`)).json(), created);
  });
  it('rejects missing name and bad ip with 422', async () => {
    assert.equal((await post({ ip: '192.168.1.70' })).status, 422);
    assert.equal((await post({ name: 'x', ip: '192.168.1.300' })).status, 422);
  });
  it('rejects broken JSON (400) and form bodies (415)', async () => {
    assert.equal((await post('{"name":')).status, 400);
    assert.equal((await post('name=x', 'application/x-www-form-urlencoded')).status, 415);
  });
});
